import borgmatic

def bash_completion():
    main_parser = borgmatic.get_parser()
    subparsers = main_parser._actions[0] if isinstance(main_parser._actions[0], argparse._SubParsersAction) else None
    completions = []

    def add_completions(parser, prefix=''):
        for action in parser._actions:
            if isinstance(action, argparse._SubParsersAction):
                for choice, subparser in action.choices.items():
                    completions.append(f"{prefix}{choice}")
                    add_completions(subparser, prefix=f"{prefix}{choice} ")
            elif isinstance(action, argparse._ArgumentGroup):
                add_completions(action, prefix)
            elif isinstance(action, argparse._HelpAction):
                continue
            else:
                if action.option_strings:
                    for opt in action.option_strings:
                        completions.append(f"{prefix}{opt}")

    add_completions(main_parser)
    completion_script = "\n".join(completions)
    return completion_script

if __name__ == "__main__":
    print(bash_completion())

