class DigestChecker:
    def error(self, message):
        print(f"Error: {message}")

    def check_digests_present_and_used(self, manifest_files, digests_used):
        manifest_digests = {file['digest'] for file in manifest_files}
        missing_digests = set(digests_used) - manifest_digests

        if missing_digests:
            self.error(f"Missing digests: {', '.join(missing_digests)}")
            return

        unused_digests = manifest_digests - set(digests_used)

        if unused_digests:
            self.error(f"Unused digests: {', '.join(unused_digests)}")
            return

        print("All required digests are present and used.")

