class InventoryValidator:
    def __init__(self, version, data):
        self.version = version
        self.data = data

    def error(self, message):
        return f"Error: {message}"

    def validate_as_prior_version(self, prior):
        if not isinstance(prior, InventoryValidator):
            return self.error("Prior is not an InventoryValidator instance")

        if prior.version >= self.version:
            return self.error("Prior version is not less than current version")

        if prior.data!= self.data:
            return self.error("Data does not match the prior version")

        return "Validation successful"

