import json

def validate_version_inventories(self, version_dirs):
    root_inventory_path = 'root_inventory.json'
    discrepancies = {}

    with open(root_inventory_path, 'r') as root_file:
        root_inventory = json.load(root_file)

    for version in version_dirs:
        version_inventory_path = os.path.join(version, 'inventory.json')

        if not os.path.exists(version_inventory_path):
            print(f"Missing inventory for version {version}")
            continue

        with open(version_inventory_path, 'r') as version_file:
            version_inventory = json.load(version_file)

        for item, root_digest in root_inventory.items():
            version_digest = version_inventory.get(item)
            if version_digest!= root_digest:
                if version not in discrepancies:
                    discrepancies[version] = []
                discrepancies[version].append((item, root_digest, version_digest))

    if discrepancies:
        for version, items in discrepancies.items():
            print(f"Discrepancies in version {version}:")
            for item, root_digest, version_digest in items:
                print(f"  Item: {item}, Root Digest: {root_digest}, Version Digest: {version_digest}")

def next_version(version):
    major, minor, patch = map(int, version.split('.'))
    patch += 1

    if patch > 99:
        patch = 0
        minor += 1

        if minor > 99:
            minor = 0
            major += 1

    return f"{major}.{minor}.{patch}"

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    num_objects = 0
    good_objects = 0

    for obj in self.objects:
        num_objects += 1
        is_valid = True

        if validate_objects:
            if not self.is_object_valid(obj):
                is_valid = False
                if show_warnings:
                    print(f"Warning: Object {obj.id} is invalid.")

        if check_digests and is_valid:
            if not self.is_digest_valid(obj):
                is_valid = False
                if show_warnings:
                    print(f"Warning: Object {obj.id} has an invalid digest.")

        if is_valid:
            good_objects += 1

