import os

def _group_files_by_xml_filename(file_list):
    grouped_files = {}
    for file_info in file_list:
        base_name = os.path.splitext(os.path.basename(file_info.filename))[0]
        if base_name.endswith('.xml'):
            base_name = base_name[:-4]
        if base_name not in grouped_files:
            grouped_files[base_name] = []
        grouped_files[base_name].append(file_info.filename)
    return grouped_files

def _explore_zipfile(zip_path):
    with zipfile.ZipFile(zip_path, 'r') as zip_file:
        file_list = zip_file.infolist()
        grouped_files = _group_files_by_xml_filename(file_list)
    return grouped_files

