def absorb(expressions):
    def apply_absorption(expr):
        parts = expr.split()
        if len(parts) == 5 and parts[1] == '&' and parts[3] == '|':
            if parts[0] == parts[4]:
                return parts[0]
        return expr

    return [apply_absorption(expr) for expr in expressions]

