def generate_default_observer_schema(app):
    default_schema = {
        "apiVersion": "v1",
        "kind": "ConfigMap",
        "metadata": {
            "name": "default-observer-schema",
            "namespace": "default"
        },
        "data": {
            "schema": "default"
        }
    }

    resources = app.spec.get('manifest', [])
    existing_schemas = app.get_existing_observer_schemas()

    for resource in resources:
        kind = resource.get('kind')
        if kind not in existing_schemas:
            resource_schema = {
                "apiVersion": resource.get("apiVersion", "v1"),
                "kind": kind,
                "metadata": {
                    "name": f"{kind.lower()}-observer-schema",
                    "namespace": resource.get("metadata", {}).get("namespace", "default")
                },
                "data": {
                    "schema": "default"
                }
            }
            app.add_observer_schema(resource_schema)

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    for key, schema in observer_schema.items():
        if isinstance(schema, dict):
            if key not in last_applied_manifest:
                last_applied_manifest[key] = {}
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[key], schema, response.get(key, {})
            )
        else:
            if key not in last_applied_manifest:
                last_applied_manifest[key] = None
            if key not in response:
                raise KeyError(f"Observed field '{key}' is not present in the Kubernetes response")
            last_applied_manifest[key] = response[key]

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    def update_recursive(last_applied, schema, resp):
        for item_schema, item_resp in zip(schema, resp):
            if isinstance(item_schema, list):
                if not isinstance(last_applied, list):
                    last_applied.append([])
                update_recursive(last_applied[-1], item_schema, item_resp)
            else:
                if item_schema not in last_applied:
                    last_applied[item_schema] = item_resp

    update_recursive(last_applied_manifest, observer_schema, response)

