class Histogram:
    def __init__(self, edges):
        self.edges = edges
        self.bins = [0.0] * (len(edges) - 1)

    def fill(self, coord, weight=1):
        if coord < self.edges[0] or coord >= self.edges[-1]:
            return

        for i in range(len(self.bins)):
            if self.edges[i] <= coord < self.edges[i + 1]:
                self.bins[i] += weight
                break

def difference(d1, d2, level=-1):
    result = {}
    for key, value in d1.items():
        if key not in d2:
            result[key] = value
        elif isinstance(value, dict) and isinstance(d2[key], dict) and level!= 0:
            sub_diff = difference(value, d2[key], level - 1 if level > 0 else level)
            if sub_diff:
                result[key] = sub_diff
    return result

