class LenaValueError(Exception):
    pass

class Graph:
    def __init__(self, scale=None, coordinates=None):
        self._scale = scale
        self.coordinates = coordinates or []

    def scale(self, other=None):
        if other is None:
            return self._scale

        if self._scale is None or self._scale == 0:
            raise LenaValueError("Cannot rescale: unknown or zero scale.")

        for coord in self.coordinates:
            if len(coord) > 0:
                coord[-1] *= other / self._scale

        self._scale = other

class Graph:
    def __init__(self, fields, errors):
        self.fields = fields
        self.errors = errors

    def _update_context(self, context):
        error_indices = [i for i, err in enumerate(self.errors) if err]
        if error_indices:
            context.setdefault('error', {}).setdefault('x_low', {})['index'] = error_indices[0]

        for field in self.fields:
            if field not in context.get('value', {}):
                context.setdefault('value', {})[field] = None

