def hist_to_graph(hist, make_value=None, get_coordinate="left", field_names=("x", "y"), scale=None):
    if make_value is None:
        make_value = lambda bin_: (bin_.content,)

    graph_data = []
    for bin_index, bin_ in enumerate(hist):
        value = make_value(bin_)
        if get_coordinate == "left":
            coordinate = bin_.left_edge
        elif get_coordinate == "right":
            coordinate = bin_.right_edge
        elif get_coordinate == "middle":
            coordinate = (bin_.left_edge + bin_.right_edge) / 2
        else:
            raise ValueError("Invalid get_coordinate value. Choose 'left', 'right', or'middle'.")

        graph_point = (coordinate,) + value
        graph_data.append(graph_point)

    graph = {name: [] for name in field_names}
    for point in graph_data:
        for name, value in zip(field_names, point):
            graph[name].append(value)

    if scale is True:
        graph['scale'] = hist.scale
    elif scale is not None:
        graph['scale'] = scale

    return graph

