from inspect import signature, Signature

def _validate_signature(method, iface_method):
    try:
        method_sig = signature(method)
        iface_sig = signature(iface_method)
        return method_sig == iface_sig
    except ValueError:
        return False

def _verify(iface, candidate, tentative=False, vtype=None):
    errors = []

    if not tentative and not providedBy(candidate):
        errors.append(f"Candidate does not provide {iface}")

    for name, iface_method in iface.names():
        if name.startswith('__'):
            continue
        try:
            candidate_method = getattr(candidate, name)
        except AttributeError:
            errors.append(f"Missing method: {name}")
            continue

        if not _validate_signature(candidate_method, iface_method):
            errors.append(f"Method {name} has incorrect signature")

    for name in iface.attrs():
        if not hasattr(candidate, name):
            errors.append(f"Missing attribute: {name}")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True

from inspect import signature
from zope.interface import Interface, Invalid, providedBy

def verifyObject(iface, candidate, tentative=False):
    errors = []

    if not tentative:
        try:
            if not providedBy(candidate, iface):
                errors.append(Invalid(f"{candidate} does not provide {iface}"))
        except Exception as e:
            errors.append(Invalid(str(e)))

    for method_name, method_iface in iface.namesAndDescriptions(2):
        if method_name not in candidate.__dict__:
            errors.append(Invalid(f"Missing method {method_name} in {candidate}"))
            continue

        candidate_method = getattr(candidate, method_name)
        method_signature = signature(method_iface)
        candidate_signature = signature(candidate_method)

        if method_signature!= candidate_signature:
            errors.append(Invalid(f"Method {method_name} in {candidate} has incorrect signature"))

    for attr_name, _ in iface.namesAndDescriptions(1):
        if not hasattr(candidate, attr_name):
            errors.append(Invalid(f"Missing attribute {attr_name} in {candidate}"))

    if errors:
        if len(errors) == 1:
            raise errors[0]
        else:
            raise Invalid("; ".join(str(e) for e in errors))

    return True

def verifyClass(iface, candidate, tentative=False):
    if not isinstance(iface, type) or not isinstance(candidate, type):
        return False

    if tentative:
        iface_methods = set(dir(iface))
        candidate_methods = set(dir(candidate))
        return iface_methods.issubset(candidate_methods)
    else:
        return issubclass(candidate, iface)

def determineMetaclass(bases, explicit_mc=None):
    if explicit_mc is not None:
        return explicit_mc

    metaclasses = set()
    for base in bases:
        meta = type(base)
        if meta is not type:
            metaclasses.add(meta)

    if not metaclasses:
        return type

    if len(metaclasses) > 1:
        raise TypeError("Multiple distinct metaclasses (%s) found" % metaclasses)

    return metaclasses.pop()

def minimalBases(classes):
    subclasses = set()
    all_classes = set()

    for cls in classes:
        base, *_, subclass = cls.split()
        all_classes.add(base)
        subclasses.add(subclass)

    return list(all_classes - subclasses)

