class LFUCache:
    def __init__(self):
        self.data = {}
        self.freq = {}
        self.freq_map = {}
        self.min_freq = 0

    def popitem(self):
        if not self.freq_map or self.min_freq not in self.freq_map:
            return None

        keys_with_min_freq = self.freq_map[self.min_freq]
        key_to_remove = keys_with_min_freq.pop()

        if not keys_with_min_freq:
            del self.freq_map[self.min_freq]

        value = self.data.pop(key_to_remove)
        freq = self.freq.pop(key_to_remove)

        if freq - 1 > 0:
            if freq - 1 not in self.freq_map:
                self.freq_map[freq - 1] = []
            self.freq_map[freq - 1].append(key_to_remove)

        return (key_to_remove, value)

from collections import OrderedDict

def lru_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = OrderedDict()

        def wrapper(*args, **kwargs):
            key = args
            if typed:
                key += tuple(sorted(kwargs.items()))
            else:
                key += tuple(kwargs.items())

            if key in cache:
                cache.move_to_end(key)
                return cache[key]

            result = func(*args, **kwargs)
            cache[key] = result
            if len(cache) > maxsize:
                cache.popitem(last=False)
            return result

        return wrapper
    return decorator

