            for i, arg in enumerate(args):
                setattr(self, f'attr_{i}', arg)

        def __repr__(self):
            attrs = ', '.join(f'{key}={getattr(self, key)}' for key in self.__dict__)
            return f'{self.__class__.__name__}({attrs})'

    if not hasattr(value, '__len__'):
        raise TypeError("The input must be a sequence with a length.")

    length = len(value)
    structure = DynamicStructure(*value)
    return structure

