def size_to_bytes(size: str) -> int:
    num_str = ''.join(filter(str.isdigit, size))
    unit = ''.join(filter(str.isalpha, size)).upper()

    units = {
        'B': 1,
        'KB': 10**3,
        'MB': 10**6,
        'GB': 10**9,
        'TB': 10**12,
        'PB': 10**15
    }

    if not unit:
        unit = 'B'

    num = int(num_str)
    return num * units.get(unit, 1)

