from datetime import timedelta

def parse_frequency(frequency):
    if frequency is None or frequency == "always":
        return None

    time_units = {
        "second": "seconds",
        "minute": "minutes",
        "hour": "hours",
        "day": "days",
        "week": "weeks",
    }

    parts = frequency.split()

    if len(parts)!= 2:
        raise ValueError("Frequency must be in the format 'number timeunit'")

    try:
        number = int(parts[0])
    except ValueError:
        raise ValueError("The number part of the frequency must be an integer")

    unit = parts[1]
    if unit not in time_units:
        raise ValueError(f"Unrecognized time unit: {unit}")

    return timedelta(**{time_units[unit]: number})

