def is_local(host):
    if host in ("localhost", "127.0.0.1"):
        return True

    try:
        ip = socket.gethostbyname(host)
    except socket.error:
        return False

    if ip.startswith("127.") or ip.startswith("192.168.") or ip.startswith("10.") or ip.startswith(("172.16.", "172.17.", "172.18.", "172.19.", "172.20.", "172.21.", "172.22.", "172.23.", "172.24.", "172.25.", "172.26.", "172.27.", "172.28.", "172.29.", "172.30.", "172.31.")):
        return True

    if host == socket.gethostname() or host == socket.getfqdn():
        return True

    if host == os.getlogin():
        return True

    return False

