import multiprocessing

def subprocess_run_helper(func_module_name, func_name, *args, timeout, extra_env=None):
    def target(queue):
        try:
            module = __import__(func_module_name)
            func = getattr(module, func_name)
            result = func(*args)
            queue.put(subprocess.CompletedProcess(args=args, returncode=0, stdout=result))
        except Exception as e:
            queue.put(subprocess.CompletedProcess(args=args, returncode=1, stdout=str(e)))

    env = os.environ.copy()
    if extra_env:
        env.update(extra_env)

    queue = multiprocessing.Queue()

    process = multiprocessing.Process(target=lambda: target(queue))
    process.start()
    process.join(timeout)

    if process.is_alive():
        process.kill()
        process.join()
        return subprocess.CompletedProcess(args=args, returncode=-1, stdout="Timeout")

    completed_process = queue.get()
    return completed_process

import os

def _resolve_string(matcher):
    groups = matcher.groupdict()
    name = groups.get('name')
    default = groups.get('default')

    if name is None:
        raise ValueError("No 'name' key found in matcher groups.")

    value = os.environ.get(name)

    if value is None:
        if default is not None:
            value = default
        else:
            raise EnvironmentError(f"Environment variable '{name}' not set and no default value provided.")

    return value

