import subprocess

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    command = [commands] + args
    process_args = {
        'cwd': cwd,
        'env': env,
       'stdout': subprocess.PIPE,
       'stderr': subprocess.PIPE if hide_stderr else subprocess.STDOUT
    }

    if verbose:
        print(f"Running command: {' '.join(command)} in {cwd}")

    process = subprocess.Popen(command, **process_args)
    stdout, stderr = process.communicate()

    result = {
       'stdout': stdout.decode('utf-8'),
       'stderr': stderr.decode('utf-8') if stderr else '',
       'returncode': process.returncode
    }

    if verbose:
        print(f"Command finished with return code {result['returncode']}")
        if result['stdout']:
            print(f"Output:\n{result['stdout']}")
        if result['stderr']:
            print(f"Errors:\n{result['stderr']}")

    return result

def is_ipv4(target):
    parts = target.split('.')
    if len(parts)!= 4:
        return False

    for part in parts:
        if not part.isdigit():
            return False
        num = int(part)
        if num < 0 or num > 255 or (num == 0 and part!= '0') or (num > 0 and part[0] == '0'):
            return False

    return True

