class SpecParser:
    def _include_groups(self, parser_dict, resolved=None, seen=None):
        if resolved is None:
            resolved = {}
        if seen is None:
            seen = set()

        dict_id = id(parser_dict)
        if dict_id in seen:
            return resolved
        seen.add(dict_id)

        for key, value in parser_dict.items():
            if isinstance(value, dict):
                if '_include' in value:
                    include_key = value['_include']
                    if include_key in parser_dict:
                        included_dict = parser_dict[include_key]
                        self._include_groups(included_dict, resolved, seen)
                        del value['_include']
                    else:
                        raise KeyError(f"Key '{include_key}' not found in parser_dict")
                else:
                    self._include_groups(value, resolved, seen)

            resolved[key] = value

        return resolved

