def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    command = ['ansible-playbook', playbook_path]

    if verbose is not None:
        command.extend(['-v'] * verbose)

    if extra_vars is not None:
        extra_vars_str =''.join(f'{key}={shlex.quote(str(value))}' for key, value in extra_vars.items())
        command.extend(['-e', extra_vars_str])

    if ansible_args is not None:
        for arg, value in ansible_args.items():
            if isinstance(value, bool):
                if value:
                    command.append(f'--{arg}')
            elif isinstance(value, list):
                for item in value:
                    command.extend([f'--{arg}', shlex.quote(str(item))])
            else:
                command.extend([f'--{arg}', shlex.quote(str(value))])

    result = subprocess.run(command, capture_output=True, text=True)

    if result.returncode == 0:
        print("Playbook executed successfully.")
    else:
        print("Playbook execution failed.")
        print(result.stdout)
        print(result.stderr)

