    type_mappings = {
       'main': {
            'arg1': int,
            'arg2': float,
            'arg3': bool,
        },
        'virsh': {
            'argA': str,
            'argB': int,
            'argC': list,
        },
        'ospd': {
            'argX': float,
            'argY': dict,
            'argZ': list,
        },
    }

    if parser_name not in type_mappings:
        return

    for arg, value in values_dict.items():
        if arg in type_mappings[parser_name]:
            expected_type = type_mappings[parser_name][arg]
            try:
                if expected_type == bool:
                    values_dict[arg] = value.lower() in ('true', '1', 'yes')
                elif expected_type == list:
                    values_dict[arg] = value.split(',')
                elif expected_type == dict:
                    values_dict[arg] = dict(item.split('=') for item in value.split(','))
                else:
                    values_dict[arg] = expected_type(value)
            except (ValueError, TypeError):
                pass

