        return 'events' in data and bool(data['events'])
    except (ValueError, TypeError):
        return False

from datetime import datetime
import pytz

def ensure_timezone(dt, default_timezone='UTC'):
    if dt.tzinfo is None:
        default_tz = pytz.timezone(default_timezone)
        return dt.replace(tzinfo=default_tz)
    return dt

def format_dt(dt):
    dt_with_tz = ensure_timezone(dt)
    return dt_with_tz.strftime('%Y-%m-%d %H:%M:%S %Z%z')

from typing import Optional
import requests

def fetch_content_type(url: str) -> Optional[str]:
    user_agent = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/58.0.3029.110 Safari/537.3"
    headers = {"User-Agent": user_agent}

    try:
        response = requests.head(url, headers=headers, timeout=5)
        response.raise_for_status()
        return response.headers.get("Content-Type")
    except requests.RequestException:
        return None

def test_tag(tag: str) -> bool:
    illegal_chars = {'<', '>', '"', '&', "'", '%', '#', '{', '}', '[', ']', ';', '=', ',', '`', '', '/', '\\', '|', '?', '*'}
    return not any(char in illegal_chars for char in tag)

