import json
from typing import Dict

def parse_diaspora_webfinger(document: str) -> Dict:
    data = json.loads(document)
    hcard_url = data['subject'].split(':')[1]
    links = data['links']
    for link in links:
        if link['rel'] == hcard_url:
            return {'hcard_url': hcard_url, 'href': link['href']}
    return {}

import re
import requests
from typing import Optional

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    match = re.match(r"acct:([^@]+)@(.+)", handle)
    if not match:
        return None

    username, domain = match.groups()
    webfinger_url = f"https://{domain}/.well-known/webfinger?resource=acct:{username}@{domain}"

    try:
        response = requests.get(webfinger_url)
        if response.status_code == 200:
            return response.text
    except requests.RequestException:
        pass

    return None

import requests
from xml.etree import ElementTree as ET

class XRD:
    def __init__(self, element):
        self.element = element
        self.services = self._parse_services()

    def _parse_services(self):
        services = []
        for service in self.element.findall('{http://docs.oasis-open.org/ns/xri/xrd-1.0}Service'):
            services.append({
                'type': service.get('{http://www.w3.org/2001/XMLSchema-instance}type'),
                'href': service.find('{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link').get('href')
            })
        return services

def retrieve_diaspora_host_meta(host):
    url = f'https://{host}/.well-known/host-meta'
    response = requests.get(url)
    response.raise_for_status()

    root = ET.fromstring(response.content)
    return XRD(root)

import requests

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    try:
        if method.lower() == "post":
            response = requests.post(url, data=data, timeout=timeout, *args, **kwargs)
        elif method.lower() == "get":
            response = requests.get(url, params=data, timeout=timeout, *args, **kwargs)
        else:
            raise ValueError("Unsupported HTTP method")
        response.raise_for_status()
        return response
    except requests.RequestException as e:
        return str(e)
